/* Formatted on 10/1/2026 12:23:30 PM (QP5 v5.362) */
DECLARE
    V_TERMINAL_ID   RAW (16);
    V_TID           VARCHAR2 (50);
BEGIN
    V_TERMINAL_ID :=
        HEXTORAW (
            REPLACE ('{{appsmith.store.MMS_SELECTED_TERMINAL_ID}}', '-', ''));
    TALY_BO_REP.MMS_TID_GENERATION_PKG.GENERATE_TID (
        P_TERMINAL_ID   => V_TERMINAL_ID,
        P_USER_ID       => '{{appsmith.user.email}}',
        P_TID           => V_TID);
    COMMIT;
END;
